import json,re,html
from pathlib import Path
root=Path(__file__).resolve().parents[1];roles=json.loads((root/'resumes/roles.json').read_text());e=html.escape
p=root/'resumes/index.html';old=p.read_text();head=old.split('<body>')[0]
head=re.sub(r'<title>.*?</title>','<title>Forward Deployed AI Engineer and Role Resumes | Shabeeb Hasan</title>',head)
head=re.sub(r'Advanced resume pack with 8 role-specific CVs[^"<]*','Role-specific resumes and project evidence for Forward Deployed AI, RAG, voice AI, backend integrations, full-stack AI, computer vision, generative media and mobile roles.',head)
head=head.replace('Shabeeb Hasan | Advanced CV Pack','Shabeeb Hasan | AI Engineering Resumes').replace('/resumes/styles.css','/resumes/application-hub.css')
head=re.sub(r'<script\b[^>]*>.*?</script>', '', head, flags=re.S)
nav=old.split('<body>',1)[1].split('<main',1)[0]
body='''<main class="page"><section class="hero"><div><p class="eyebrow">SHABEEB HASAN · KARACHI, UTC+5</p><h1>Forward Deployed<br><span>AI Engineer</span></h1><p class="lead">I turn customer workflows into working AI applications, integrations and product features.</p><p class="support">12+ years in software delivery · 133 completed client contracts · 71% repeat engagements</p><div class="actions"><a class="button primary" href="/resumes/files/forward-deployed-ai-resume.pdf" download>Download primary resume</a><a class="button" href="/case-studies/">See project evidence</a></div></div><aside class="focus-card"><span class="eyebrow">PRIMARY FOCUS</span><h2>AI agents, RAG<br>and integrations</h2><p>Customer discovery → implementation → testing → handover</p><a href="#roles">Choose the resume for your role ↓</a></aside></section>
<section class="match-panel" aria-labelledby="match-heading"><div><p class="eyebrow">MATCH A JOB</p><h2 id="match-heading">Find the right resume</h2><p>Paste a job title or description to compare relevant resume categories. Check the project evidence and role requirements before choosing.</p><p class="privacy">Your text stays in this browser.</p></div><div><label for="job-text">Job title or description</label><textarea id="job-text" rows="5" maxlength="15000" placeholder="For example: customer-facing AI engineer, Python APIs, RAG and deployment"></textarea><div class="actions"><button id="match" class="button primary" type="button">Match resume</button><button id="clear-job" class="button" type="button">Clear</button></div><div id="matches" aria-live="polite"></div></div></section>
<section id="roles"><div class="section-title"><div><p class="eyebrow">EIGHT ROLE CATEGORIES</p><h2>Same experience. Relevant evidence.</h2></div><div><label class="sr-only" for="role-search">Search role categories</label><input id="role-search" type="search" placeholder="Search a role or skill"></div></div><div class="filters" aria-label="Resume categories"><button class="active" data-filter="all" aria-pressed="true">All roles</button><button data-filter="primary" aria-pressed="false">Primary focus</button><button data-filter="core" aria-pressed="false">Core engineering</button><button data-filter="specialist" aria-pressed="false">Specialist AI</button><button data-filter="adjacent" aria-pressed="false">Mobile</button></div><p id="role-count" class="muted" aria-live="polite">8 resume categories</p><div class="role-grid">'''
for r in roles:
 band='primary' if r['id']=='forward-deployed-ai' else 'core' if r['band'].startswith('Core') else 'adjacent' if r['band'].startswith('Adjacent') else 'specialist'
 body+=f'''<article class="role-card {'featured' if band=='primary' else ''}" id="{r['id']}" data-id="{r['id']}" data-band="{band}"><div class="card-label">{e(r['band'])}</div><h3>{e(r['title'])}</h3><p class="subtitle">{e(r['subtitle'])}</p><p>{e(r['use_when'])}</p><div class="skills">'''+''.join('<span>'+e(k)+'</span>' for k in r['skills'][:6])+'''</div><details><summary>Relevant projects and role fit</summary><ul>'''
 for project in r['projects']:body+=f'<li><a href="{e(project["url"])}">{e(project["title"])}</a><small>{e(project["kind"])}</small></li>'
 body+='</ul><p class="fit-note">'+e(r['check_before_applying'])+'</p></details>'
 body+=f'''<div class="card-actions"><a class="button primary" href="{r['public_pdf']}" download>Download resume</a><a class="text-link" href="{r['public_pdf']}" target="_blank" rel="noopener">Preview PDF ↗</a></div><div class="secondary-actions"><a href="{r['marketplace_pdf']}" download>Marketplace copy</a><a href="{r['text_file']}" download>Editable text</a><button type="button" data-copy="{r['id']}">Copy intro</button></div><span class="copy-status" aria-live="polite"></span></article>'''
body+='''</div><p id="empty-roles" hidden>No matching category. Clear the search or choose another category.</p></section><section class="legacy"><h2>Additional formats</h2><p>Existing specialist and visual CVs remain available.</p><div class="legacy-links"><a href="/resumes/files/06-php-laravel-cv.pdf">PHP / Laravel</a><a href="/resumes/files/07-aws-cloud-backend-cv.pdf">AWS Cloud Backend</a><a href="/resumes/files/08-python-django-cv.pdf">Python / Django</a><a href="/resumes/files/02-data-scientist-cv.pdf">Data Science / ML</a></div></section><footer><a href="/portfolio/">Portfolio</a><a href="/contact/">Contact</a><span>Project scope, ownership and prototype status are identified in each resume.</span></footer></main><script src="/resumes/application-hub.js" defer></script></body></html>'''
p.write_text('\n'.join(line.rstrip() for line in (head+'<body>'+nav+body).splitlines())+'\n')
# Align the home page with the same focused positioning and primary resume.
p=root/'index.html';s=p.read_text();s=s.replace('Hire an AI and Full-Stack Developer | Shabeeb Hasan','Forward Deployed AI Engineer | AI Agents, RAG and Integrations | Shabeeb Hasan')
s=s.replace('Senior AI & Full-Stack Engineer | Data Scientist | Forward Deployed Engineer','Forward Deployed AI Engineer | AI Agents, RAG and Integrations')
s=s.replace('Senior AI &amp; Full-Stack Engineer &middot; Python, React Native, LLM, RAG, AWS','Forward Deployed AI Engineer &middot; AI Agents, RAG &amp; Integrations')
s=s.replace('Founders hire me to build the AI part their product is missing, then to keep it running.','I work with customer teams to turn real workflows into AI applications and reliable integrations.')
s=s.replace('Nine recruiter-friendly CVs position the same delivery history for AI engineering, forward deployed engineering, data science, React Native, full-stack AI, PHP/Laravel, AWS cloud, Python/Django, and ATS screening workflows.','Choose from eight focused role resumes, each with matching project evidence, a single-column PDF and an editable text version. Forward Deployed AI Engineering is my primary focus.')
s=s.replace('View CV Hub','Choose a role resume')
s=s.replace('<a href="/resumes/files/01-ai-engineer-cv.pdf" target="_blank" rel="noopener">AI Engineer CV</a>','<a href="/resumes/files/forward-deployed-ai-resume.pdf" target="_blank" rel="noopener">Forward Deployed AI Engineer</a>')
s=s.replace('href="/resumes/files/02-data-scientist-cv.pdf" target="_blank" rel="noopener">Data Scientist CV','href="/resumes/files/applied-ai-rag-resume.pdf" target="_blank" rel="noopener">Applied AI and RAG')
s=s.replace('href="/resumes/files/05-ats-one-page-cv.pdf" target="_blank" rel="noopener">ATS One-Page CV','href="/resumes/files/voice-ai-resume.pdf" target="_blank" rel="noopener">Voice AI and Messaging')
if 'href="/resumes/">Role resumes' not in s:s=s.replace('<div class="hero-actions">','<div class="hero-actions"><a class="btn btn-outline-light btn-rounded" href="/resumes/">Role resumes</a>',1)
s=s.replace('<div class="brand-subtitle">Senior AI &amp; Full-Stack Engineer</div>','<div class="brand-subtitle">Forward Deployed AI Engineer</div>')
s=s.replace('<span>Senior AI &amp; Full-Stack Engineer &middot; MPhil ML &amp; Data Science</span>','<span>Forward Deployed AI Engineer &middot; MPhil Computer Science</span>')
links=''.join('<a href="'+r['public_pdf']+'" target="_blank" rel="noopener">'+e(r['title'])+'</a>' for r in roles)
s=re.sub(r'(<div class="cv-grid">).*?(</div>)',lambda m:m[1]+links+m[2],s,count=1,flags=re.S)
modal=''.join('<a href="'+r['public_pdf']+'" class="list-group-item list-group-item-action" download>'+e(r['title'])+' (PDF)</a>' for r in roles)
s=re.sub(r'(<div class="modal fade" id="cvDownloadModal".*?<div class="list-group">).*?(</div>)',lambda m:m[1]+modal+m[2],s,count=1,flags=re.S)
p.write_text(s)
